const body = $input.first().json.body;
const required = ['employee_name', 'last_day', 'role', 'department'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const lastDay = new Date(body.last_day);
if (isNaN(lastDay)) return [{ json: { valid: false, error: 'last_day must be valid (YYYY-MM-DD)' } }];
const today = new Date(); today.setHours(0,0,0,0);
const daysRemaining = Math.floor((lastDay - today) / 86400000);
const depTypes = ['voluntary', 'involuntary', 'retirement', 'contract_end', 'layoff'];
const departureType = depTypes.includes(body.departure_type) ? body.departure_type : 'voluntary';
return [{ json: {
  valid: true,
  employeeName: body.employee_name.trim(),
  role: body.role.trim(),
  department: body.department.trim(),
  lastDay: body.last_day,
  daysRemaining: Math.max(0, daysRemaining),
  departureType,
  managerId: body.manager_name || '',
  managerEmail: body.manager_email || '',
  hrEmail: body.hr_email || '',
  systems: Array.isArray(body.systems_access) ? body.systems_access : (body.systems_access||'').split(',').map(s=>s.trim()).filter(Boolean),
  directReports: parseInt(body.direct_reports) || 0,
  clientFacing: body.client_facing === true || body.client_facing === 'true',
  companyEquipment: Array.isArray(body.company_equipment) ? body.company_equipment : (body.company_equipment||'').split(',').map(e=>e.trim()).filter(Boolean),
  replyEmail: body.reply_email || null
} }];

values.content:
Generate an offboarding checklist.

Employee: {{ $json.employeeName }}
Role: {{ $json.role }}
Department: {{ $json.department }}
Last day: {{ $json.lastDay }}
Days remaining: {{ $json.daysRemaining }}
Departure type: {{ $json.departureType }}
Manager: {{ $json.managerId || 'not specified' }}
Systems access: {{ $json.systems.join(', ') || 'not specified' }}
Direct reports: {{ $json.directReports }}
Client-facing: {{ $json.clientFacing }}
Equipment to return: {{ $json.companyEquipment.join(', ') || 'not specified' }}

Return this JSON:
{
  "offboarding_summary": "2-3 sentences: key considerations for this specific offboarding",
  "phases": [
    {
      "phase": "Immediate (day 1 of notice)",
      "items": [
        {
          "task": "specific task",
          "owner": "HR | Manager | IT | Employee | Legal | Finance",
          "is_blocker": false,
          "notes": "any specific detail"
        }
      ]
    }
  ],
  "access_revocation_list": ["specific systems to revoke — use the systems provided plus infer standard ones for the role"],
  "knowledge_transfer_topics": ["specific knowledge areas this employee should document or hand off — based on role"],
  "client_transition_steps": ["specific steps for client-facing transitions — null if not client-facing"],
  "legal_compliance_items": ["NDA reminders, IP agreements, non-compete considerations, benefits continuation"],
  "equipment_return_list": ["items to return with condition documentation notes"],
  "exit_interview_questions": ["5-6 questions calibrated to this role and departure type"],
  "manager_talking_points": ["what to cover in the offboarding conversation with the employee"]
}

