const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let checklist;
try { checklist = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
checklist._meta = { employeeName: input.employeeName, role: input.role, department: input.department, lastDay: input.lastDay, daysRemaining: input.daysRemaining, departureType: input.departureType, managerEmail: input.managerEmail, hrEmail: input.hrEmail, replyEmail: input.replyEmail };
return [{ json: checklist }];

const c = $input.first().json;
const m = c._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const ownerColors = {HR:'#7c3aed', Manager:'#2563eb', IT:'#16a34a', Employee:'#d97706', Legal:'#dc2626', Finance:'#0891b2'};
const deptColors = {'Immediate (day 1 of notice)':'#dc2626','First 24-48 hours':'#ea580c','Week 1':'#d97706','Week 2 or before last week':'#2563eb','Final week':'#16a34a','Last day':'#6b7280'};
const phaseBlocks = (c.phases||[]).map(ph => {
  const phColor = Object.keys(deptColors).find(k => ph.phase.toLowerCase().includes(k.toLowerCase().slice(0,5))) ? deptColors[Object.keys(deptColors).find(k => ph.phase.toLowerCase().includes(k.toLowerCase().slice(0,5)))] : '#6b7280';
  const items = (ph.items||[]).map(item => {
    const oc = ownerColors[item.owner] || '#6b7280';
    return `<div style="display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #f3f4f6;align-items:flex-start">
      <input type="checkbox" style="margin-top:3px;flex-shrink:0">
      <div style="flex:1">
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:2px">
          <span style="font-size:14px;font-weight:${item.is_blocker?'700':'500'}">${esc(item.task)}</span>
          ${item.is_blocker?'<span style="background:#fef2f2;color:#dc2626;font-size:10px;font-weight:700;padding:1px 7px;border-radius:8px">URGENT</span>':''}
        </div>
        <div style="display:flex;gap:8px">
          <span style="background:${oc}22;color:${oc};font-size:11px;padding:2px 8px;border-radius:8px;font-weight:600">${esc(item.owner)}</span>
        </div>
        ${item.notes?`<div style="font-size:12px;color:#6b7280;margin-top:4px">${esc(item.notes)}</div>`:''}
      </div>
    </div>`;
  }).join('');
  return `<div style="margin-bottom:20px"><div style="background:#f8faff;border-left:4px solid ${phColor};padding:8px 14px;margin-bottom:10px;border-radius:0 6px 6px 0"><div style="font-size:14px;font-weight:700;color:#1e293b">${esc(ph.phase)}</div></div>${items}</div>`;
}).join('');
const accessList = (c.access_revocation_list||[]).map(a => `<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #fef2f2;color:#7f1d1d">✗ ${esc(a)}</div>`).join('');
const ktList = (c.knowledge_transfer_topics||[]).map(k => `<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #f0f9ff;color:#1e40af">→ ${esc(k)}</div>`).join('');
const exitQs = (c.exit_interview_questions||[]).map((q,i) => `<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #f3f4f6">${i+1}. ${esc(q)}</div>`).join('');
const legalItems = (c.legal_compliance_items||[]).map(l => `<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #f5f3ff;color:#6d28d9">⚖ ${esc(l)}</div>`).join('');
const dtColors = {voluntary:'#16a34a', involuntary:'#dc2626', retirement:'#2563eb', contract_end:'#d97706', layoff:'#ea580c'};
const dtColor = dtColors[m.departureType] || '#6b7280';
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#1e293b;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;color:#64748b;margin-bottom:4px">Employee Offboarding · ${esc(m.departureType.replace(/_/g,' '))}</div>
    <div style="font-size:19px;font-weight:700">${esc(m.employeeName)}</div>
    <div style="font-size:13px;color:#94a3b8;margin-top:3px">${esc(m.role)} · ${esc(m.department)} · Last day: ${esc(m.lastDay)} (${m.daysRemaining} days)</div>
  </div>
  <div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:none;display:flex;gap:12px;align-items:center">
    <span style="background:${dtColor};color:#fff;font-size:12px;font-weight:700;padding:3px 12px;border-radius:10px">${esc(m.departureType.replace(/_/g,' ').toUpperCase())}</span>
    <p style="font-size:14px;color:#374151;margin:0;line-height:1.6">${esc(c.offboarding_summary)}</p>
  </div>
  <div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">${phaseBlocks}</div>
  ${accessList?`<div style="background:#fef2f2;padding:14px 28px;border:1px solid #fecaca"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:8px">Access to revoke</div>${accessList}</div>`:''}
  ${ktList?`<div style="background:#eff6ff;padding:14px 28px;border:1px solid #bfdbfe"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px">Knowledge transfer topics</div>${ktList}</div>`:''}
  ${legalItems?`<div style="background:#f5f3ff;padding:14px 28px;border:1px solid #ddd6fe"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#6d28d9;margin-bottom:8px">Legal & compliance</div>${legalItems}</div>`:''}
  ${exitQs?`<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Exit interview questions</div>${exitQs}</div>`:''}
  <div style="background:#1e293b;color:#475569;font-size:11px;padding:10px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">Employee Offboarding · ${esc(m.employeeName)} · Last day ${esc(m.lastDay)}</div>
</div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, managerEmail: m.managerEmail, hrEmail: m.hrEmail, employeeName: m.employeeName, lastDay: m.lastDay, checklist: c } }];

const emails = [$json.managerEmail, $json.hrEmail, $json.replyEmail].filter(Boolean);
const unique = [...new Set(emails)];
return [{ json: { ...$json, allRecipients: unique } }];
